const now = new Date();
const pad = n => String(n).padStart(2, '0');
const y = now.getUTCFullYear();
const m = pad(now.getUTCMonth() + 1);
const d = pad(now.getUTCDate());
return [{ json: { reportDate: y + '-' + m + '-' + d } }];

const camp = $('Split in Batches').item.json;
const reportDate = $('Set Report Date').first().json.reportDate;

// Parse line-area-chart-stats: Sent, Replied, Bounced, Unique Opens, Interested
const statsJson = $('HTTP Campaign Stats').item.json;
let sentCount = 0, replyCount = 0, bounceCount = 0, uniqueOpenCount = 0, positiveRepliesCount = 0;
if (statsJson && statsJson.data && Array.isArray(statsJson.data)) {
  for (const item of statsJson.data) {
    const dateEntry = (item.dates || []).find(d => d[0] === reportDate);
    const val = dateEntry ? (dateEntry[1] || 0) : 0;
    if (item.label === 'Sent')           sentCount = val;
    else if (item.label === 'Replied')   replyCount = val;
    else if (item.label === 'Bounced')   bounceCount = val;
    else if (item.label === 'Unique Opens') uniqueOpenCount = val;
    else if (item.label === 'Interested')   positiveRepliesCount = val;
  }
}

// Parse sender-emails: meta.total = inboxes_active
const inboxJson = $('HTTP Campaign Inboxes').item.json;
const inboxesActive = (inboxJson && inboxJson.meta) ? (inboxJson.meta.total || 0) : 0;

return [{ json: {
  campaign_id: camp.campaign_id,
  report_date: reportDate,
  sent_count: sentCount,
  reply_count: replyCount,
  bounce_count: bounceCount,
  unique_open_count: uniqueOpenCount,
  positive_replies_count: positiveRepliesCount,
  inboxes_active: inboxesActive
} }];
